from pathlib import Path


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected exactly 1 match, found {count}')
    return text.replace(old, new, 1)


# Customer-order item contract.
path = Path('src/utils/customerOrders.ts')
text = path.read_text()
text = replace_once(text, "  transferredQuantity: number;\n  note: string;", "  transferredQuantity: number;\n  voidedQuantity?: number;\n  note: string;", 'customer item type')
text = replace_once(text, "  Math.max(0, item.quantity - item.paidQuantity - item.transferredQuantity);", "  Math.max(\n    0,\n    item.quantity - item.paidQuantity - item.transferredQuantity - (item.voidedQuantity ?? 0)\n  );", 'open quantity')
text = replace_once(text, "    (sum, item) => sum + Math.max(0, item.quantity - item.transferredQuantity),", "    (sum, item) =>\n      sum + Math.max(0, item.quantity - item.transferredQuantity - (item.voidedQuantity ?? 0)),", 'billable quantity')
text = replace_once(text, "      transferredQuantity: 0,\n      note: cleanString(input.itemNotes[product.id]),", "      transferredQuantity: 0,\n      voidedQuantity: 0,\n      note: cleanString(input.itemNotes[product.id]),", 'customer builder')
text = replace_once(text, "    const transferredQuantity = finiteNumber(record.transferredQuantity) ?? 0;\n\n    if (", "    const transferredQuantity = finiteNumber(record.transferredQuantity) ?? 0;\n    const voidedQuantity = finiteNumber(record.voidedQuantity) ?? 0;\n\n    if (", 'parse voided')
text = replace_once(text, "      !Number.isInteger(transferredQuantity) ||\n      transferredQuantity < 0 ||\n      paidQuantity + transferredQuantity > quantity", "      !Number.isInteger(transferredQuantity) ||\n      transferredQuantity < 0 ||\n      !Number.isInteger(voidedQuantity) ||\n      voidedQuantity < 0 ||\n      paidQuantity + transferredQuantity + voidedQuantity > quantity", 'validate voided')
text = replace_once(text, "      transferredQuantity,\n      note: cleanString(record.note),", "      transferredQuantity,\n      voidedQuantity,\n      note: cleanString(record.note),", 'parse output')
text = replace_once(text, "    transferredQuantity: item.transferredQuantity,\n    note: item.note,", "    transferredQuantity: item.transferredQuantity,\n    voidedQuantity: item.voidedQuantity ?? 0,\n    note: item.note,", 'equivalence')
path.write_text(text)

# Table operations.
path = Path('src/utils/legacyTableOperations.ts')
text = path.read_text()
text = replace_once(text, "export interface AppliedTableTransfer {\n  updatedSourceOrders: CustomerOrder[];\n  targetOrders: CustomerOrder[];\n  amount: number;\n  quantity: number;\n}\n", "export interface AppliedTableTransfer {\n  updatedSourceOrders: CustomerOrder[];\n  targetOrders: CustomerOrder[];\n  amount: number;\n  quantity: number;\n}\n\nexport interface TableItemExclusionReceipt {\n  exclusionId: string;\n  orderId: string;\n  lineId: string;\n  tableCode: string;\n  productId: string;\n  itemName: string;\n  quantity: number;\n  amount: number;\n  createdAt: string;\n}\n", 'receipt type')
text = replace_once(text, "interface TransferTableItemsInput {\n  storeId: string;\n  sourceTableCode: string;\n  targetTableCode: string;\n  selections: TableItemSelection[];\n}\n", "interface TransferTableItemsInput {\n  storeId: string;\n  sourceTableCode: string;\n  targetTableCode: string;\n  selections: TableItemSelection[];\n}\n\ninterface ExcludeTableItemInput {\n  storeId: string;\n  tableCode: string;\n  orderId: string;\n  lineId: string;\n}\n", 'exclude input')
text = replace_once(text, "      transferredQuantity: 0,\n      note: note.trim(),", "      transferredQuantity: 0,\n      voidedQuantity: 0,\n      note: note.trim(),", 'staff builder')
text = replace_once(text, "        transferredQuantity: 0,\n      });", "        transferredQuantity: 0,\n        voidedQuantity: 0,\n      });", 'transfer target')
marker = "export const getTablePaymentMethodLabel = (\n  method: TablePaymentMethod\n): string => {"
if text.count(marker) != 1:
    raise SystemExit('payment label marker not found uniquely')
exclusion_fn = '''export const excludeTableItem = async (\n  user: Pick<User, 'uid' | 'email' | 'displayName'>,\n  input: ExcludeTableItemInput\n): Promise<TableItemExclusionReceipt> => {\n  const tableCode = normalizeTableCode(input.tableCode);\n  const orderId = input.orderId.trim();\n  const lineId = input.lineId.trim();\n\n  if (user.uid !== input.storeId) {\n    throw new Error('Somente a loja autenticada pode excluir itens da conta.');\n  }\n  if (!tableCode || !orderId || !lineId) {\n    throw new Error('Item da conta não identificado.');\n  }\n\n  const orderReference = doc(db, getCustomerOrderDocumentPath(input.storeId, orderId));\n  const exclusionReference = doc(\n    collection(db, `artifacts/${input.storeId}/public/data/tableItemExclusions`)\n  );\n  let receipt: TableItemExclusionReceipt | null = null;\n\n  await runTransaction(db, async transaction => {\n    const snapshot = await transaction.get(orderReference);\n    const order = parseCustomerOrder(snapshot.data());\n    if (!order) throw new Error('O pedido não foi encontrado.');\n    if (\n      order.fulfillmentType !== 'dine_in' ||\n      tableKey(order.tableCode) !== tableKey(tableCode) ||\n      isTerminalCustomerOrderStatus(order.status)\n    ) {\n      throw new Error('O item não está em uma conta ativa desta mesa.');\n    }\n\n    const sourceItem = order.items.find(item => item.lineId === lineId);\n    if (!sourceItem) throw new Error('O item selecionado não foi encontrado.');\n    const availableQuantity = getCustomerOrderItemOpenQuantity(sourceItem);\n    if (availableQuantity <= 0) {\n      throw new Error('Este item já não possui quantidade em aberto.');\n    }\n\n    const createdAt = new Date().toISOString();\n    const nextItems = order.items.map(item =>\n      item.lineId === lineId\n        ? { ...item, voidedQuantity: (item.voidedQuantity ?? 0) + availableQuantity }\n        : item\n    );\n    const allItemsClosed = nextItems.every(\n      item => getCustomerOrderItemOpenQuantity(item) === 0\n    );\n    const nextSubtotal = nextItems.reduce(\n      (sum, item) =>\n        sum + item.price * Math.max(0, item.quantity - (item.voidedQuantity ?? 0)),\n      0\n    );\n\n    transaction.update(orderReference, {\n      items: nextItems,\n      subtotal: nextSubtotal,\n      total: nextSubtotal,\n      status: allItemsClosed ? 'cancelled' : order.status,\n      updatedAt: createdAt,\n    });\n\n    const nextReceipt: TableItemExclusionReceipt = {\n      exclusionId: exclusionReference.id,\n      orderId: order.id,\n      lineId: sourceItem.lineId,\n      tableCode,\n      productId: sourceItem.productId,\n      itemName: sourceItem.name,\n      quantity: availableQuantity,\n      amount: sourceItem.price * availableQuantity,\n      createdAt,\n    };\n    receipt = nextReceipt;\n    transaction.set(exclusionReference, {\n      ...nextReceipt,\n      storeId: input.storeId,\n      unitPrice: sourceItem.price,\n      previousOrderStatus: order.status,\n      operatorId: user.uid,\n      operatorName: operatorNameFor(user),\n      reason: '',\n      authorizationMode: 'temporary_simple_exclusion',\n    });\n  });\n\n  if (!receipt) throw new Error('Não foi possível excluir o item da conta.');\n  return receipt;\n};\n\n'''
text = text.replace(marker, exclusion_fn + marker, 1)
path.write_text(text)

